using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct EncounterId : IEquatable<EncounterId>, IComparable<EncounterId>
    {
        public Guid Value { get; }

        public EncounterId(Guid value)
        {
            Value = value;
        }

        public static EncounterId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static EncounterId NewRandom() => new EncounterId(Guid.NewGuid());

        public static EncounterId Parse(string text) => new EncounterId(Guid.Parse(text));

        public static bool TryParse(string text, out EncounterId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new EncounterId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(EncounterId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is EncounterId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(EncounterId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(EncounterId left, EncounterId right) => left.Equals(right);

        public static bool operator !=(EncounterId left, EncounterId right) => !left.Equals(right);
    }
}
